// A base64-embedded copy of the logo icon (not a Vite asset import) —
// the print-agent's headless renderer calls page.setContent() with raw
// HTML and no origin/base URL, so a normal bundled asset path (e.g.
// "/assets/marasi-logo-icon-abc123.webp") cannot resolve there; a data
// URI works identically in both the browser print dialog and the
// print-agent's screenshot path since it needs no network fetch.
export const marasiLogoIconDataUri = "data:image/webp;base64,";
